async function waitFor(condition, within = WAIT_WITHIN) {
  const began = performance.now();
  while (!condition()) {
    if (performance.now() - began >= within) throw new Error(`the condition ${condition} did not hold within ${within} ms`);
    await oneTurn();
  }
}

