function recordingSink(onEmit = () => {}) {
  const events = [];
  const sink = {
    emitter: ({ layer }) => ({
      emit(event, fields) {
        onEmit(event, fields);
        events.push({ layer, event, ...fields });
      },
    }),
  };
  return { sink, events };
}

