  if (ending === 'C7') {
    assert.match(ran.text, /remote get-url origin` exited 7/, ran.text);
    return;
  }
  if (ending === 'C6' && !original.includes('git-hold')) {
    assert.match(ran.text, /the remote it named ends in no owner and name/, ran.text);
    return;
  }
