function reaperState(run) {
  const ps = spawnSync('/bin/ps', ['-axo', 'pid=,stat=,command='], { encoding: 'utf8' });
  const row = ps.stdout.split('\n').find((line) => line.includes('test/suite-reaper') && line.includes(run));
  return row?.trim() ?? null;
}

