      "  writeFileSync(directory + '/hold', '');",
      "  const parent = spawn(fixture(directory, 'parent', leave(TAIL, 'tail')), [], { stdio: 'ignore' });",
      "  await once(parent, 'exit');",
      "  const fixturePid = Number(read(directory, 'tail.pid'));",
      "  process.kill(fixturePid, 0);",
    ] : kind === 'F3' ? [
      "  writeFileSync(directory + '/hold', '');",
