      "  const dispatch = runCommand({ command: '/bin/sh', args: [command], cwd: directory, env: process.env, timeout: 600_000, emitter: { emit() {} }, onGroup: (pid) => writeFileSync(directory + '/group.pid', String(pid)) });",
