        assert.equal(actual.actual.signal, null); assert.equal(actual.actual.error, null);
        const heldRow = /^[ \t]*([0-9]+)[ \t]+([0-9]+)[ \t]+([A-Za-z][A-Za-z+<>]*)[ \t]*\n?$/.exec(actual.actual.stdout);
