            const answer = spawnSync('/bin/ps', ['-p', String(auxiliary.pid), '-o', 'pid=,stat='], { encoding: 'utf8', timeout: Math.max(1, Math.ceil(cleanupDeadline - performance.now())), killSignal: 'SIGKILL' });
