function reportsPassedTest(output, title) {
  return output.split('\n').some((line) =>
    line.startsWith(`✔ ${title} (`) ||
    (/^ok [0-9]+ - /.test(line) && line.replace(/^ok [0-9]+ - /, '') === title));
}

