  const source = "import { writeFileSync } from 'node:fs';\nimport { spawnSync } from 'node:child_process';\ntest('records TMPDIR', () => { writeFileSync(process.env.MARKER, process.env.TMPDIR); spawnSync('git', ['--version']); });";
